// The imagination window — the detached surface opened by `bsc widget open imagination`.
// What the ear heard, as pictures: the newest thought's image, the scene it was
// understood to be, and the transcript underneath it.
//
// WHY IT POLLS RATHER THAN SUBSCRIBES. The producer is a separate process
// (`bsc imagine`), deliberately, so that a slow or crashed renderer cannot stall
// this window. A file-backed feed read on a timer is the honest expression of
// that: there is no socket to go stale, and a producer that dies mid-thought
// leaves a readable feed rather than a half-open subscription.
//
// FOUR STATES, NOT ONE. `absent` means nobody is imagining; `empty` means the
// room is quiet. Those look identical on disk and must never look identical
// here — a surface that reads "nothing" while the thing behind it is not running
// is the failure this codebase keeps re-learning. `failing` carries the reason.

import { useCallback, useEffect, useRef, useState } from "react";
import { invoke } from "@tauri-apps/api/core";
import { Box } from "@/shared/ui/layout/Box";
import { Stack } from "@/shared/ui/layout/Stack";
import { Text } from "@/shared/ui/typography/Text";

/** How hard the renderer thought about one entry. Mirrors `bsc_imagine::Tier`. */
export type Tier = "reflex" | "considered" | "deliberate";

/** One thought. Mirrors `bsc_imagine::Entry`. */
export interface Entry {
  id: string;
  at_unix_ms: number;
  transcript: string;
  /** Absent when the transcript was drawn directly — a faster path, not a degraded one. */
  scene?: string | null;
  image: string;
  tier: Tier;
  render_ms: number;
}

/** Mirrors `bsc_imagine::FeedState` (serde tag = "state"). */
export type FeedState =
  | { state: "absent" }
  | { state: "empty" }
  | { state: "ready"; entries: Entry[] }
  | { state: "failing"; reason: string };

/** How often the feed is re-read. The reflex tier renders in ~205 ms, so a second is
 *  comfortably faster than thoughts arrive and cheap enough to leave running. */
export const POLL_MS = 1000;

/** The headline for a state, and the detail under it.
 *
 *  Pure and exported so the four states can be pinned by a test without a
 *  filesystem, a producer or a GPU — the distinction between `absent` and
 *  `empty` is the one thing here most worth a guard.
 */
export function describeState(s: FeedState): { headline: string; detail: string } {
  switch (s.state) {
    case "absent":
      return {
        headline: "Nothing is imagining",
        detail: "No producer has run. Start one with `bsc imagine watch`.",
      };
    case "empty":
      return {
        headline: "Listening",
        detail: "A producer is running and the room has been quiet.",
      };
    case "failing":
      return { headline: "Imagination failed", detail: s.reason };
    case "ready":
      return {
        headline: `${s.entries.length} thought${s.entries.length === 1 ? "" : "s"}`,
        detail: "",
      };
  }
}

/** The newest entry, or null. By time, never by position. */
export function newestEntry(s: FeedState): Entry | null {
  if (s.state !== "ready" || s.entries.length === 0) return null;
  return s.entries.reduce((a, b) => (b.at_unix_ms > a.at_unix_ms ? b : a));
}

/** "4s ago" / "2m ago" — how old a thought is, which matters because a stale picture
 *  is still a thought and must not pretend to be current. */
export function ageLabel(atMs: number, nowMs: number): string {
  const s = Math.max(0, Math.round((nowMs - atMs) / 1000));
  if (s < 60) return `${s}s ago`;
  const m = Math.round(s / 60);
  if (m < 60) return `${m}m ago`;
  return `${Math.round(m / 60)}h ago`;
}

/** The live surface. */
export function ImaginationWidget() {
  const [feed, setFeed] = useState<FeedState>({ state: "absent" });
  const [image, setImage] = useState<string | null>(null);
  const [now, setNow] = useState(() => Date.now());
  // Which entry the loaded image belongs to, so a re-poll that changes nothing
  // does not re-fetch a few hundred kilobytes every second.
  const loadedFor = useRef<string | null>(null);

  const poll = useCallback(async () => {
    try {
      const next = await invoke<FeedState>("imagination_feed");
      setFeed(next);
      setNow(Date.now());
      const newest = newestEntry(next);
      if (!newest) {
        loadedFor.current = null;
        setImage(null);
        return;
      }
      if (loadedFor.current === newest.id) return;
      try {
        const uri = await invoke<string>("imagination_image", { id: newest.id });
        loadedFor.current = newest.id;
        setImage(uri);
      } catch {
        // The entry exists but its picture does not — the producer died between
        // the log line and the file. Keep the words; drop the stale picture
        // rather than showing a previous thought's image beside new text.
        loadedFor.current = null;
        setImage(null);
      }
    } catch (e) {
      setFeed({ state: "failing", reason: e instanceof Error ? e.message : String(e) });
    }
  }, []);

  useEffect(() => {
    void poll();
    const t = setInterval(() => void poll(), POLL_MS);
    return () => clearInterval(t);
  }, [poll]);

  const newest = newestEntry(feed);
  const { headline, detail } = describeState(feed);

  return (
    <Box style={{ height: "100%", overflow: "auto", padding: 16 }}>
      <Stack gap={12}>
        <Box
          style={{
            width: "100%",
            aspectRatio: "1 / 1",
            background: "var(--bg-subtle, #111)",
            border: "1px solid var(--border, #333)",
            borderRadius: 8,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            overflow: "hidden",
          }}
        >
          {image ? (
            <img
              src={image}
              alt={newest?.scene ?? newest?.transcript ?? "the newest thought"}
              style={{ width: "100%", height: "100%", objectFit: "cover" }}
            />
          ) : (
            <Stack gap={4} style={{ padding: 24, textAlign: "center" }}>
              <Text as="div" mono tone={feed.state === "failing" ? "danger" : "dim"}>
                {headline}
              </Text>
              {detail ? (
                <Text as="div" mono tone="dim" size="sm">
                  {detail}
                </Text>
              ) : null}
            </Stack>
          )}
        </Box>

        {newest ? (
          <Stack gap={6}>
            {newest.scene ? (
              <Text as="div">{newest.scene}</Text>
            ) : (
              <Text as="div" tone="dim">
                drawn straight from what was heard
              </Text>
            )}
            <Text as="div" mono tone="dim" size="sm">
              “{newest.transcript}”
            </Text>
            <Text as="div" mono tone="dim" size="sm">
              {newest.tier} · {newest.render_ms}ms · {ageLabel(newest.at_unix_ms, now)}
            </Text>
          </Stack>
        ) : null}
      </Stack>
    </Box>
  );
}

