import { describe, it, expect, vi, beforeEach } from "vitest";
import { render, screen, waitFor } from "@testing-library/react";
import { invoke } from "@tauri-apps/api/core";
import {
  ImaginationWidget,
  describeState,
  newestEntry,
  ageLabel,
  type Entry,
  type FeedState,
} from "@/features/imagination/ImaginationWidget";

const entry = (over: Partial<Entry> = {}): Entry => ({
  id: "a",
  at_unix_ms: 1_000,
  transcript: "it is raining",
  scene: "a wet street at night",
  image: "a.png",
  tier: "reflex",
  render_ms: 205,
  ...over,
});

/** Drive the two commands the widget calls. */
function mockFeed(state: FeedState, image: string | Error = "data:image/png;base64,AAA") {
  vi.mocked(invoke).mockImplementation(((cmd: string) => {
    if (cmd === "imagination_feed") return Promise.resolve(state);
    if (cmd === "imagination_image") {
      return image instanceof Error ? Promise.reject(image) : Promise.resolve(image);
    }
    return Promise.reject(new Error(`unexpected command ${cmd}`));
  }) as unknown as typeof invoke);
}

beforeEach(() => {
  vi.mocked(invoke).mockReset();
});

describe("the four feed states", () => {
  it("says nobody is imagining, distinctly from the room being quiet", () => {
    // THE distinction this component exists to preserve. A surface that reads
    // "nothing" while the producer is not running is the failure this codebase
    // keeps re-learning, so these two must never render the same words.
    const absent = describeState({ state: "absent" });
    const empty = describeState({ state: "empty" });
    expect(absent.headline).not.toEqual(empty.headline);
    expect(absent.detail).not.toEqual(empty.detail);
    expect(absent.detail).toMatch(/bsc imagine/);
  });

  it("carries a failure's reason rather than a generic message", () => {
    const d = describeState({ state: "failing", reason: "no image generator on PATH" });
    expect(d.detail).toBe("no image generator on PATH");
  });

  it("counts thoughts with correct pluralisation", () => {
    expect(describeState({ state: "ready", entries: [entry()] }).headline).toBe("1 thought");
    expect(
      describeState({ state: "ready", entries: [entry(), entry({ id: "b" })] }).headline,
    ).toBe("2 thoughts");
  });
});

describe("newestEntry", () => {
  it("picks by time, not by position", () => {
    const s: FeedState = {
      state: "ready",
      entries: [entry({ id: "mid", at_unix_ms: 5 }), entry({ id: "new", at_unix_ms: 9 }), entry({ id: "old", at_unix_ms: 1 })],
    };
    expect(newestEntry(s)?.id).toBe("new");
  });

  it("is null for every state that has no entries", () => {
    expect(newestEntry({ state: "absent" })).toBeNull();
    expect(newestEntry({ state: "empty" })).toBeNull();
    expect(newestEntry({ state: "ready", entries: [] })).toBeNull();
    expect(newestEntry({ state: "failing", reason: "x" })).toBeNull();
  });
});

describe("ageLabel", () => {
  it("reads in the unit that fits, and never goes negative", () => {
    expect(ageLabel(1_000, 5_000)).toBe("4s ago");
    expect(ageLabel(0, 120_000)).toBe("2m ago");
    expect(ageLabel(0, 7_200_000)).toBe("2h ago");
    // A clock that stepped backwards must not render "-3s ago".
    expect(ageLabel(9_000, 1_000)).toBe("0s ago");
  });
});

describe("the widget", () => {
  it("renders the absent state when no producer has run", async () => {
    mockFeed({ state: "absent" });
    render(<ImaginationWidget />);
    expect(await screen.findByText(/Nothing is imagining/)).toBeTruthy();
  });

  it("renders the scene and the transcript for the newest thought", async () => {
    mockFeed({ state: "ready", entries: [entry()] });
    render(<ImaginationWidget />);
    expect(await screen.findByText("a wet street at night")).toBeTruthy();
    expect(await screen.findByText(/it is raining/)).toBeTruthy();
    expect(await screen.findByText(/reflex · 205ms/)).toBeTruthy();
  });

  it("shows the image once it loads, described by the scene", async () => {
    mockFeed({ state: "ready", entries: [entry()] });
    render(<ImaginationWidget />);
    const img = (await screen.findByAltText("a wet street at night")) as HTMLImageElement;
    expect(img.src).toContain("data:image/png;base64");
  });

  it("keeps the words when the picture is missing, rather than showing a stale one", async () => {
    // The producer died between writing the log line and the file. Showing the
    // PREVIOUS thought's image beside new text would be a lie.
    mockFeed({ state: "ready", entries: [entry()] }, new Error("no such file"));
    render(<ImaginationWidget />);
    expect(await screen.findByText("a wet street at night")).toBeTruthy();
    expect(screen.queryByAltText("a wet street at night")).toBeNull();
  });

  it("says so when a thought was drawn straight from what was heard", async () => {
    mockFeed({ state: "ready", entries: [entry({ scene: null })] });
    render(<ImaginationWidget />);
    expect(await screen.findByText(/drawn straight from what was heard/)).toBeTruthy();
  });

  it("surfaces a failed command as a failing feed rather than staying blank", async () => {
    vi.mocked(invoke).mockRejectedValue(new Error("the backend is not there"));
    render(<ImaginationWidget />);
    expect(await screen.findByText(/the backend is not there/)).toBeTruthy();
  });

  it("does not refetch the image while the newest thought is unchanged", async () => {
    // At a few hundred kilobytes a second this is the difference between an
    // ambient surface and a busy one.
    mockFeed({ state: "ready", entries: [entry()] });
    render(<ImaginationWidget />);
    await screen.findByAltText("a wet street at night");
    const imageCalls = () =>
      vi.mocked(invoke).mock.calls.filter((c) => c[0] === "imagination_image").length;
    expect(imageCalls()).toBe(1);
    // A second poll of the same feed must not fetch the picture again.
    await waitFor(() => expect(vi.mocked(invoke).mock.calls.filter((c) => c[0] === "imagination_feed").length).toBeGreaterThan(0));
    expect(imageCalls()).toBe(1);
  });
});
